    @BeforeClass
    public static void setUpClass() {
        // Set up the Document instance for testing
        doc = new Document(BASE_URI);
        titleEl = null;
    }

    @Before
    public void setUp() {
        // Reset the title element before each test
        titleEl = null;
    }

    @Test
    public void testTitleNullInput() {
        Assert.assertThrows(IllegalArgumentException.class, () -> doc.title(null));
    }

    @Test
    public void testTitleEmptyInput() {
        Assert.assertThrows(IllegalArgumentException.class, () -> doc.title(""));
    }

    @Test
    public void testTitleAddToHead() {
        // Given: No title element exists
        Elements elements = doc.getElementsByTag("title");
        Assert.assertFalse(elements.size() > 0);

        // When: Title is set with an empty title element
        doc.title(TITLE);

        // Then: The title element should exist and contain the correct text
        elements = doc.getElementsByTag("title");
        Assert.assertTrue(elements.size() > 0);
        titleEl = elements.first();
        Assert.assertEquals(TITLE, titleEl.text());
    }

    @Test
    public void testTitleUpdateExisting() {
        // Given: A title element already exists with the correct text
        doc.head().appendElement("title").text(TITLE);
        titleEl = doc.getElementsByTag("title").first();

        // When: Title is set again with the same text
        doc.title(TITLE);

        // Then: The existing title element should not be replaced
        Assert.assertEquals(TITLE, titleEl.text());
    }

    @Test
    public void testTitleUpdateExistingWithDifferentText() {
        // Given: A title element already exists with different text
        doc.head().appendElement("title").text("Original Title");
        titleEl = doc.getElementsByTag("title").first();

        // When: Title is set again with a new text
        doc.title(TITLE);

        // Then: The existing title element should be replaced with the new one
        Assert.assertEquals(TITLE, titleEl.text());
    }

    @Test
    public void testTitleOutput() {
        // Given: A title element exists with the correct text
        doc.head().appendElement("title").text(TITLE);
        titleEl = doc.getElementsByTag("title").first();

        // When: The document's outer HTML is retrieved
        String output = doc.outerHtml();

        // Then: The output should contain the correct title element
        Assert.assertThat(output, containsString("<title>" + TITLE + "</title>"));
    }
}
