    private static Cleaner cleaner;
    private static Element root;
    private static Element destination;
    private static Node source;
    private static int depth = 0;

    @Rule
    public ExpectedException expectedEx = ExpectedException.none();

    @BeforeClass
    public static void setup() {
        cleaner = new Cleaner(new Whitelist());
        root = Element.parse("<html><body><div id='root'><h1>Test</h1></div></body></html>");
        destination = root;
    }

    @Before
    public void setupEach() {
        cleaner.traverse(root);
        source = root.child(0).child(0);
    }

    @Test
    public void testTail_Element_WhitelistTag() {
        destination = destination.parent();
        cleaner.traverse(source, depth + 1);
        Assert.assertEquals("h1", source.nodeName());
    }

