    public void testSetValue_WithInvalidInput_ThrowsIllegalArgumentException() {
        Attribute invalidAttribute = new Attribute(null, "invalid");
        Assert.assertThrows(IllegalArgumentException.class, () -> invalidAttribute.setValue("newValue"));
    }

