    public void testHtml_WithValidInput_ReturnsCorrectOutput() throws IOException {
        String expected = " key=\"value\"";
        String actual = attribute.html();
        Assert.assertEquals(expected, actual);
    }

    @Test
    public void testIsDataAttribute_ReturnsTrueForDataAttributes() {
        Attribute dataAttribute = new Attribute("data-test", "value");
        assertTrue(dataAttribute.isDataAttribute());
    }

    @Test
    public void testIsDataAttribute_ReturnsFalseForNonDataAttributes() {
        assertFalse(attribute.isDataAttribute());
    }

    @Test
    public void testIsBooleanAttribute_ReturnsTrueForBooleanAttributes() {
        Attribute booleanAttribute = new Attribute("checked", "true");
        assertTrue(booleanAttribute.isBooleanAttribute());
    }

    @Test
    public void testIsBooleanAttribute_ReturnsFalseForNonBooleanAttributes() {
        assertFalse(attribute.isBooleanAttribute());
    }

    @Test
    public void testEquals_ReturnsTrueForEqualObjects() {
        Attribute equalAttribute = new Attribute("key", "value");
        assertTrue(attribute.equals(equalAttribute));
    }

    @Test
    public void testEquals_ReturnsFalseForUnequalObjects() {
        Attribute unequalAttribute = new Attribute("unequalKey", "value");
        assertFalse(attribute.equals(unequalAttribute));
    }

    @Test
    public void testHashCode_ReturnsSameValueForEqualObjects() {
        Attribute equalAttribute = new Attribute("key", "value");
        int hashCode1 = attribute.hashCode();
        int hashCode2 = equalAttribute.hashCode();
        assertEquals(hashCode1, hashCode2);
    }

    @Test
    public void testClone_ReturnsCorrectClone() {
        Attribute clone = attribute.clone();
        Assert.assertEquals("key", clone.getKey());
        Assert.assertEquals("value", clone.getValue());
    }
}
